# Save as: recover_rsa_small_e.py
# Usage: python3 recover_rsa_small_e.py
# Requires: gmpy2 (pip install gmpy2)

import gmpy2

n = gmpy2.mpz()
e = 20
c = gmpy2.mpz()

m, exact = gmpy2.iroot(c, e)

def to_bytes(x):
    bl = int(x).bit_length()
    return int(x).to_bytes((bl + 7) // 8, 'big')

if exact:
    pt = to_bytes(m)
    print("Recovered plaintext (bytes):", pt)
    try:
        print("Recovered plaintext (utf-8):", pt.decode())
    except UnicodeDecodeError:
        pass
else:
    print("Ciphertext is not a perfect e-th power. Try the SageMath script for Coppersmith.")
